const STAGES = ['待投递', '已投递', '面试中', '已结束'];
const ALL = '全部';
const KEY = 'applications';

const el = (role) => document.querySelector('[data-role="' + role + '"]');

const ui = {
  formTitle: el('form-title'),
  formError: el('form-error'),
  listError: el('list-error'),
  company: el('company'),
  position: el('position'),
  date: el('date'),
  stage: el('stage'),
  note: el('note'),
  submit: el('submit'),
  cancelEdit: el('cancel-edit'),
  resetForm: el('reset-form'),
  list: el('list'),
  empty: el('empty'),
  listCount: el('list-count'),
  filters: el('filters'),
  dialogMask: el('dialog-mask'),
  dialogText: el('dialog-text'),
  dialogCancel: el('dialog-cancel'),
  dialogConfirm: el('dialog-confirm')
};

const statCards = Array.prototype.slice.call(document.querySelectorAll('.stat-card'));
const chips = Array.prototype.slice.call(document.querySelectorAll('.chip'));

let records = [];
let filter = ALL;
let editingId = null;
let pendingDeleteId = null;
let dialogResolver = null;

function todayStr() {
  const d = new Date();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return d.getFullYear() + '-' + m + '-' + day;
}

function normalizeStage(value) {
  return STAGES.indexOf(value) >= 0 ? value : STAGES[0];
}

function normalizeRecord(raw) {
  const src = raw && typeof raw === 'object' ? raw : {};
  return {
    id: typeof src.id === 'string' && src.id ? src.id : 'r-' + Date.now() + '-' + Math.random().toString(36).slice(2, 8),
    company: typeof src.company === 'string' ? src.company : '',
    position: typeof src.position === 'string' ? src.position : '',
    date: typeof src.date === 'string' ? src.date : '',
    stage: normalizeStage(src.stage),
    note: typeof src.note === 'string' ? src.note : '',
    createdAt: typeof src.createdAt === 'number' ? src.createdAt : Date.now()
  };
}

function showError(node, message) {
  if (!node) return;
  if (message) {
    node.textContent = message;
    node.hidden = false;
  } else {
    node.textContent = '';
    node.hidden = true;
  }
}

function setFormError(message) {
  showError(ui.formError, message);
}

function setListError(message) {
  showError(ui.listError, message);
}

function readForm() {
  return {
    company: ui.company.value.trim(),
    position: ui.position.value.trim(),
    date: ui.date.value,
    stage: normalizeStage(ui.stage.value),
    note: ui.note.value.trim()
  };
}

function clearForm() {
  ui.company.value = '';
  ui.position.value = '';
  ui.date.value = todayStr();
  ui.stage.value = STAGES[0];
  ui.note.value = '';
  setFormError('');
}

function enterEditMode(record) {
  editingId = record.id;
  ui.company.value = record.company;
  ui.position.value = record.position;
  ui.date.value = record.date;
  ui.stage.value = record.stage;
  ui.note.value = record.note;
  ui.formTitle.textContent = '编辑投递记录';
  ui.submit.textContent = '保存修改';
  ui.cancelEdit.hidden = false;
  setFormError('');
  ui.company.focus();
}

function exitEditMode() {
  editingId = null;
  ui.formTitle.textContent = '新增投递记录';
  ui.submit.textContent = '保存记录';
  ui.cancelEdit.hidden = true;
  clearForm();
}

function countByStage() {
  const counts = { 全部: records.length };
  STAGES.forEach(function (s) { counts[s] = 0; });
  records.forEach(function (r) {
    if (counts[r.stage] === undefined) counts[r.stage] = 0;
    counts[r.stage] += 1;
  });
  return counts;
}

function renderStats() {
  const counts = countByStage();
  statCards.forEach(function (card) {
    const key = card.getAttribute('data-filter');
    const num = card.querySelector('.stat-num');
    if (num) num.textContent = String(counts[key] === undefined ? 0 : counts[key]);
    card.classList.toggle('is-active', key === filter);
  });
  chips.forEach(function (chip) {
    chip.classList.toggle('is-active', chip.getAttribute('data-filter') === filter);
  });
}

function buildRecordItem(record) {
  const li = document.createElement('li');
  li.className = 'record';
  li.setAttribute('data-id', record.id);

  const top = document.createElement('div');
  top.className = 'record-top';

  const info = document.createElement('div');
  const company = document.createElement('h3');
  company.className = 'record-company';
  company.textContent = record.company || '（未填写公司）';
  const position = document.createElement('p');
  position.className = 'record-position';
  position.textContent = record.position || '（未填写岗位）';
  info.appendChild(company);
  info.appendChild(position);

  const badge = document.createElement('span');
  badge.className = 'badge';
  badge.setAttribute('data-stage', record.stage);
  badge.textContent = record.stage;

  top.appendChild(info);
  top.appendChild(badge);
  li.appendChild(top);

  const meta = document.createElement('p');
  meta.className = 'record-meta';
  meta.textContent = '投递日期：' + (record.date || '未填写');
  li.appendChild(meta);

  if (record.note) {
    const note = document.createElement('p');
    note.className = 'record-note';
    note.textContent = record.note;
    li.appendChild(note);
  }

  const actions = document.createElement('div');
  actions.className = 'record-actions';

  const editBtn = document.createElement('button');
  editBtn.type = 'button';
  editBtn.className = 'btn btn-ghost';
  editBtn.textContent = '编辑';
  editBtn.addEventListener('click', function () {
    const target = records.filter(function (r) { return r.id === record.id; })[0];
    if (target) enterEditMode(target);
  });

  const delBtn = document.createElement('button');
  delBtn.type = 'button';
  delBtn.className = 'btn btn-del';
  delBtn.textContent = '删除';
  delBtn.addEventListener('click', function () {
    requestDelete(record);
  });

  actions.appendChild(editBtn);
  actions.appendChild(delBtn);
  li.appendChild(actions);

  return li;
}

function renderList() {
  const visible = filter === ALL
    ? records.slice()
    : records.filter(function (r) { return r.stage === filter; });

  visible.sort(function (a, b) {
    const da = a.date || '';
    const db = b.date || '';
    if (da !== db) return db.localeCompare(da);
    return (b.createdAt || 0) - (a.createdAt || 0);
  });

  ui.list.textContent = '';
  visible.forEach(function (record) {
    ui.list.appendChild(buildRecordItem(record));
  });

  ui.listCount.textContent = '共 ' + visible.length + ' 条';
  ui.empty.hidden = visible.length !== 0;
  if (visible.length === 0) {
    const title = ui.empty.querySelector('.empty-title');
    const desc = ui.empty.querySelector('.empty-desc');
    if (records.length === 0) {
      title.textContent = '暂无投递记录';
      desc.textContent = '在上方填写公司和岗位，点击「保存记录」开始记录你的求职进度。';
    } else {
      title.textContent = '该阶段暂无记录';
      desc.textContent = '当前筛选为「' + filter + '」，可切换到其他阶段查看。';
    }
  }
}

function render() {
  renderStats();
  renderList();
}

async function persist(nextRecords) {
  const state = await appStore.getState();
  const base = state && typeof state === 'object' ? state : {};
  const next = Object.assign({}, base);
  next[KEY] = nextRecords;
  await appStore.setState(next);
}

async function saveRecords(nextRecords) {
  const previous = records;
  records = nextRecords;
  render();
  try {
    await persist(nextRecords);
    setListError('');
    return true;
  } catch (err) {
    records = previous;
    render();
    setListError('保存失败，数据未写入，请重试。');
    return false;
  }
}

function openDialog(message) {
  ui.dialogText.textContent = message;
  ui.dialogMask.hidden = false;
  return new Promise(function (resolve) {
    dialogResolver = resolve;
  });
}

function closeDialog(result) {
  ui.dialogMask.hidden = true;
  const resolve = dialogResolver;
  dialogResolver = null;
  if (resolve) resolve(result);
}

async function requestDelete(record) {
  const label = (record.company || '该记录') + (record.position ? ' · ' + record.position : '');
  const ok = await openDialog('确定要删除「' + label + '」这条投递记录吗？删除后无法恢复。');
  if (!ok) return;
  const next = records.filter(function (r) { return r.id !== record.id; });
  const saved = await saveRecords(next);
  if (saved && editingId === record.id) {
    exitEditMode();
  }
}

async function handleSubmit() {
  const data = readForm();
  if (!data.company) {
    setFormError('请填写公司名称。');
    ui.company.focus();
    return;
  }
  if (!data.position) {
    setFormError('请填写岗位名称。');
    ui.position.focus();
    return;
  }
  setFormError('');

  let next;
  if (editingId) {
    next = records.map(function (r) {
      if (r.id !== editingId) return r;
      return Object.assign({}, r, data);
    });
  } else {
    const record = normalizeRecord(Object.assign({}, data, {
      id: 'r-' + Date.now() + '-' + Math.random().toString(36).slice(2, 8),
      createdAt: Date.now()
    }));
    next = records.concat([record]);
  }

  const saved = await saveRecords(next);
  if (saved) {
    exitEditMode();
  }
}

function bindEvents() {
  ui.submit.addEventListener('click', function () {
    handleSubmit();
  });

  ui.cancelEdit.addEventListener('click', function () {
    exitEditMode();
  });

  ui.resetForm.addEventListener('click', function () {
    exitEditMode();
  });

  ui.filters.addEventListener('click', function (event) {
    const target = event.target.closest('.chip');
    if (!target) return;
    filter = target.getAttribute('data-filter') || ALL;
    render();
  });

  statCards.forEach(function (card) {
    card.addEventListener('click', function () {
      filter = card.getAttribute('data-filter') || ALL;
      render();
    });
  });

  ui.dialogCancel.addEventListener('click', function () {
    closeDialog(false);
  });

  ui.dialogConfirm.addEventListener('click', function () {
    closeDialog(true);
  });

  ui.dialogMask.addEventListener('click', function (event) {
    if (event.target === ui.dialogMask) closeDialog(false);
  });

  document.addEventListener('keydown', function (event) {
    if (event.key === 'Escape' && !ui.dialogMask.hidden) {
      closeDialog(false);
    }
  });
}

async function init() {
  bindEvents();
  clearForm();

  let state = null;
  try {
    state = await appStore.getState();
  } catch (err) {
    state = null;
  }

  const base = state && typeof state === 'object' ? state : {};
  const rawList = Array.isArray(base[KEY]) ? base[KEY] : null;

  if (rawList === null) {
    records = [];
    try {
      await persist([]);
    } catch (err) {
      setListError('初始化数据失败，本次修改可能无法保存。');
    }
  } else {
    records = rawList.map(normalizeRecord);
  }

  render();
}

await init();

artifact.css:
:root {
  --blue-700: #1d4ed8;
  --blue-600: #2563eb;
  --blue-500: #3b82f6;
  --blue-100: #dbeafe;
  --blue-50: #eff6ff;
  --ink: #1e293b;
  --ink-soft: #64748b;
  --line: #e2e8f0;
  --bg: #f5f8ff;
  --white: #ffffff;
  --danger: #dc2626;
  --danger-soft: #fee2e2;
  --radius: 14px;
}

* { box-sizing: border-box; }

.wrap {
  max-width: 720px;
  margin: 0 auto;
  padding: 16px 14px 48px;
  color: var(--ink);
  font-size: 15px;
  line-height: 1.55;
}

.topbar {
  background: linear-gradient(135deg, var(--blue-600), var(--blue-500));
  color: #fff;
  border-radius: var(--radius);
  padding: 18px 18px 20px;
  box-shadow: 0 8px 20px rgba(37, 99, 235, 0.22);
}

.title {
  margin: 0;
  font-size: 20px;
  font-weight: 700;
  letter-spacing: 0.5px;
}

.subtitle {
  margin: 6px 0 0;
  font-size: 13px;
  opacity: 0.9;
}

.stats {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 8px;
  margin-top: 14px;
}

.stat-card {
  appearance: none;
  border: 1px solid var(--line);
  background: var(--white);
  border-radius: 12px;
  padding: 10px 4px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  cursor: pointer;
  font-family: inherit;
  color: var(--ink);
  transition: border-color 0.15s, background 0.15s, transform 0.1s;
}

.stat-card:active { transform: scale(0.97); }

.stat-card.is-active {
  border-color: var(--blue-500);
  background: var(--blue-50);
}

.stat-num {
  font-size: 18px;
  font-weight: 700;
  color: var(--blue-700);
}

.stat-label {
  font-size: 11px;
  color: var(--ink-soft);
  white-space: nowrap;
}

.panel {
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 16px 14px;
  margin-top: 16px;
  box-shadow: 0 2px 10px rgba(30, 64, 175, 0.05);
}

.panel-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 12px;
}

.panel-title {
  margin: 0;
  font-size: 16px;
  font-weight: 700;
  color: var(--blue-700);
}

.field { margin-bottom: 12px; }

.field-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}

.field label {
  display: block;
  font-size: 13px;
  font-weight: 600;
  color: var(--ink-soft);
  margin-bottom: 5px;
}

.req { color: var(--danger); }

.field input,
.field select,
.field textarea {
  width: 100%;
  font-family: inherit;
  font-size: 15px;
  color: var(--ink);
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: 10px;
  padding: 10px 11px;
  outline: none;
  transition: border-color 0.15s, box-shadow 0.15s;
}

.field textarea { resize: vertical; }

.field input:focus,
.field select:focus,
.field textarea:focus {
  border-color: var(--blue-500);
  box-shadow: 0 0 0 3px var(--blue-100);
}

.form-actions {
  display: flex;
  gap: 10px;
  margin-top: 4px;
}

.btn {
  appearance: none;
  font-family: inherit;
  font-size: 15px;
  font-weight: 600;
  border-radius: 10px;
  padding: 10px 16px;
  cursor: pointer;
  border: 1px solid transparent;
  transition: background 0.15s, border-color 0.15s, transform 0.1s;
}

.btn:active { transform: scale(0.98); }

.btn-primary {
  background: var(--blue-600);
  color: #fff;
  flex: 1;
}

.btn-primary:hover { background: var(--blue-700); }

.btn-ghost {
  background: var(--white);
  color: var(--blue-700);
  border-color: var(--blue-100);
}

.btn-ghost:hover { background: var(--blue-50); }

.btn-danger {
  background: var(--danger);
  color: #fff;
}

.btn-danger:hover { background: #b91c1c; }

.form-error,
.list-error {
  background: var(--danger-soft);
  color: #991b1b;
  border: 1px solid #fecaca;
  border-radius: 10px;
  padding: 9px 11px;
  font-size: 13px;
  margin-bottom: 12px;
}

.list-error { margin: 0 0 12px; }

.list-section { margin-top: 20px; }

.list-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 10px;
}

.list-count {
  font-size: 13px;
  color: var(--ink-soft);
}

.filters {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 12px;
}

.chip {
  appearance: none;
  font-family: inherit;
  font-size: 13px;
  font-weight: 600;
  color: var(--blue-700);
  background: var(--white);
  border: 1px solid var(--blue-100);
  border-radius: 999px;
  padding: 6px 14px;
  cursor: pointer;
  transition: background 0.15s, color 0.15s, border-color 0.15s;
}

.chip.is-active {
  background: var(--blue-600);
  border-color: var(--blue-600);
  color: #fff;
}

.record-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.record {
  background: var(--white);
  border: 1px solid var(--line);
  border-left: 4px solid var(--blue-500);
  border-radius: 12px;
  padding: 12px 13px;
  box-shadow: 0 2px 8px rgba(30, 64, 175, 0.05);
}

.record-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 10px;
}

.record-company {
  margin: 0;
  font-size: 16px;
  font-weight: 700;
  word-break: break-word;
}

.record-position {
  margin: 3px 0 0;
  font-size: 13px;
  color: var(--ink-soft);
  word-break: break-word;
}

.badge {
  flex: none;
  font-size: 12px;
  font-weight: 700;
  border-radius: 999px;
  padding: 3px 10px;
  white-space: nowrap;
  background: var(--blue-50);
  color: var(--blue-700);
  border: 1px solid var(--blue-100);
}

.badge[data-stage="已投递"] { background: #e0f2fe; color: #0369a1; border-color: #bae6fd; }
.badge[data-stage="面试中"] { background: #fef3c7; color: #b45309; border-color: #fde68a; }
.badge[data-stage="已结束"] { background: #f1f5f9; color: #475569; border-color: #e2e8f0; }

.record-meta {
  margin: 8px 0 0;
  font-size: 13px;
  color: var(--ink-soft);
}

.record-note {
  margin: 6px 0 0;
  font-size: 13px;
  color: var(--ink);
  background: var(--blue-50);
  border-radius: 8px;
  padding: 7px 9px;
  white-space: pre-wrap;
  word-break: break-word;
}

.record-actions {
  display: flex;
  gap: 8px;
  margin-top: 10px;
}

.record-actions .btn {
  font-size: 13px;
  padding: 7px 14px;
}

.btn-del {
  background: var(--white);
  color: var(--danger);
  border-color: #fecaca;
}

.btn-del:hover { background: var(--danger-soft); }

.empty {
  background: var(--white);
  border: 1px dashed var(--blue-100);
  border-radius: var(--radius);
  padding: 28px 18px;
  text-align: center;
}

.empty-title {
  margin: 0;
  font-size: 15px;
  font-weight: 700;
  color: var(--blue-700);
}

.empty-desc {
  margin: 6px 0 0;
  font-size: 13px;
  color: var(--ink-soft);
}

.dialog-mask {
  position: fixed;
  inset: 0;
  background: rgba(15, 23, 42, 0.45);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  z-index: 50;
}

.dialog {
  background: var(--white);
  border-radius: var(--radius);
  padding: 18px 16px 16px;
  width: 100%;
  max-width: 340px;
  box-shadow: 0 18px 40px rgba(15, 23, 42, 0.28);
}

.dialog-title {
  margin: 0;
  font-size: 16px;
  font-weight: 700;
  color: var(--ink);
}

.dialog-text {
  margin: 8px 0 16px;
  font-size: 14px;
  color: var(--ink-soft);
  word-break: break-word;
}

.dialog-actions {
  display: flex;
  gap: 10px;
  justify-content: flex-end;
}

@media (max-width: 420px) {
  .stats { grid-template-columns: repeat(3, 1fr); }
  .field-row { grid-template-columns: 1fr; }
  .wrap { padding: 12px 10px 40px; }
}
